33	// FileReaderFunc is a function that opens an imported file by name.
34	// It is the functional form of FileReaders: a plain function can be
35	// passed straight to Parse without any wrapper type.
36	//
37	// Implementations are used through FileReaders.Open semantics: the
38	// returned reader is always fully consumed and closed by the parser,
39	// and names are normalized, tree-relative paths (see
40	// normalizeImportPath).
41	type FileReaderFunc func(name string) (io.ReadCloser, error)
42	
43	// Open implements FileReaders.
44	func (f FileReaderFunc) Open(name string) (io.ReadCloser, error) {
45		return f(name)
46	}
47	
48	// FileReaders abstracts the files an import directive may resolve.
49	//
50	// Parsing only ever reads imported files through the value given to
51	// one Parse call: a single parse never consults the operating system
52	// behind the caller's back, and replacing or reusing readers between
53	// (or during) calls cannot mix versions into a result.
54	//
55	// A plain open function (FileReaderFunc) is enough for exact, named
56	// imports. Use FromFS to adapt an io/fs.FS (which also carries Glob
57	// and ReadDir) when import directives use wildcard patterns. A
58	// FileReaders value that additionally implements Glob(pattern)
59	// ([]string, error) provides glob matches directly.
60	type FileReaders interface {
61		Open(name string) (io.ReadCloser, error)
62	}
63	
64	// fileGlobber is the optional glob capability a FileReaders value may
65	// provide. Matches must use the same normalized, tree-relative path
66	// space as Open.
67	type fileGlobber interface {
68		Glob(pattern string) ([]string, error)
69	}
70	
71	// FromFS adapts an io/fs.FS to FileReaders. Because io/fs declares
72	// Open with a different return type, an fs.FS does not satisfy
73	// FileReaders structurally; FromFS performs the adaptation. When the
74	// underlying FS supports it, the returned value also resolves import
75	// globs (fs.GlobFS or directory listing); otherwise glob patterns
76	// simply have no matches.
77	func FromFS(fsys fs.FS) FileReaders {
78		return fsReader{fsys: fsys}
79	}
80	
81	// fsReader adapts an io/fs.FS.
82	type fsReader struct {
83		fsys fs.FS
84	}
85	
86	// Open implements FileReaders: an fs.File always provides Read and
87	// Close, so it doubles as an io.ReadCloser.
88	func (f fsReader) Open(name string) (io.ReadCloser, error) {
89		file, err := f.fsys.Open(name)
90		if err != nil {
91			return nil, err
92		}
93		return file, nil
94	}
95	
96	// Glob enumerates glob matches when the underlying FS can.
97	func (f fsReader) Glob(pattern string) ([]string, error) {
98		if g, ok := f.fsys.(fs.GlobFS); ok {
99			return g.Glob(pattern)
100		}
101		// fs.Glob needs directory listing; an FS that cannot list simply
102		// yields no matches rather than an error.
103		if _, ok := f.fsys.(fs.ReadDirFS); !ok {
104			return nil, nil
105		}
106		return fs.Glob(f.fsys, pattern)
107	}
108	
109	var _ FileReaders = FileReaderFunc(nil)
110	var _ FileReaders = fsReader{}
111	
112	// importSource is one Parse call's self-contained view of importable
113	// files. It holds the caller's readers and caches every read and glob
114	// result for the duration of the call, so:
115	//
116	//   - each imported file is opened at most once, and every later use
117	//     (a repeated import, another glob hit, a nested import) expands
118	//     the same bytes;
119	//   - a reader that returns different contents on a second open
120	//     cannot change tokens already produced by the call;
121	//   - concurrent Parse calls have separate importSource values, so
122	//     readers may be reused freely without shared state.
123	//
124	// A nil readers value selects the operating system filesystem and the
125	// historical import behavior.
126	type importSource struct {
127		readers FileReaders
128	
129		// files caches the snapshot bytes of every opened file by its
130		// normalized path.
131		files map[string][]byte
132	
133		// globs caches every resolved match list by normalized pattern so
134		// the same pattern observed twice in a call expands identically.
135		globs map[string][]string
136	}
137	
138	// newImportSource returns a fresh source for one Parse call. Nothing
139	// is read eagerly; the first import drives the snapshot.
140	func newImportSource(readers FileReaders) *importSource {
141		return &importSource{
142			readers: readers,
143			files:   make(map[string][]byte),
144			globs:   make(map[string][]string),
145		}
146	}
147	
148	// onDisk reports whether imports resolve against the operating system
149	// filesystem, which keeps historical path and error behavior.
150	func (s *importSource) onDisk() bool { return s.readers == nil }
151	
152	// readFile returns the contents of name, which is a normalized path
153	// (virtual) or an on-disk path. The first successful read is cached and
154	// copied, so callers cannot mutate the snapshot and a reused reader
155	// cannot smuggle new bytes into the call.
156	func (s *importSource) readFile(name string) ([]byte, error) {
157		if cached, ok := s.files[name]; ok {
158			out := make([]byte, len(cached))
159			copy(out, cached)
160			return out, nil
161		}
162	
163		var input []byte
164		if s.readers == nil {
165			data, err := readDiskFile(name)
166			if err != nil {
167				return nil, err
168			}
169			input = data
170		} else {
171			rc, err := s.readers.Open(name)
172			if err != nil {
173				return nil, err
174			}
175			data, readErr := readAllAndClose(rc)
176			if readErr != nil {
177				return nil, readErr
178			}
179			input = data
180		}
181	
182		// cache a private copy of the snapshot bytes
183		cached := make([]byte, len(input))
184		copy(cached, input)
185		s.files[name] = cached
186		return input, nil
187	}
188	
189	// readAllAndClose drains f, treating a directory opened through any
190	// reader the same way os.File reports one, and always closing it.
191	func readAllAndClose(f io.ReadCloser) ([]byte, error) {
192		defer f.Close()
193		// Stat is optional: os.File and map-backed files provide it, but a
194		// bare io.ReadCloser does not. A directory that cannot be statted
195		// still fails when read.
196		if st, ok := f.(interface{ Stat() (fs.FileInfo, error) }); ok {
197			if info, err := st.Stat(); err == nil && info.IsDir() {
198				return nil, errImportIsDir
199			}
200		}
201		return io.ReadAll(f)
202	}
203	
204	// readDiskFile opens, stats, and reads an on-disk import target.
205	func readDiskFile(name string) ([]byte, error) {
206		file, err := os.Open(name)
207		if err != nil {
208			return nil, err
209		}
210		defer file.Close()
211	
212		info, err := file.Stat()
213		if err != nil {
214			return nil, err
215		}
216		if info.IsDir() {
217			return nil, errImportIsDir
218		}
219		return io.ReadAll(file)
220	}
221	
222	// glob enumerates matches for an already-resolved, normalized (or
223	// on-disk) pattern. Results are cached per call and, for virtual
224	// readers, deterministically sorted.
225	func (s *importSource) glob(pattern string) ([]string, error) {
226		if matches, ok := s.globs[pattern]; ok {
227			return matches, nil
228		}
229	
230		var matches []string
231		var err error
232		if s.readers == nil {
233			matches, err = filepath.Glob(pattern)
234		} else {
235			matches, err = globWithReader(s.readers, pattern)
236		}
237		if err != nil {
238			return nil, err
239		}
240	
241		// normalize, deduplicate, and sort virtual matches so expansion
242		// order is stable regardless of the reader's enumeration order or
243		// path spelling; filepath.Glob already returns clean, sorted names
244		if s.readers != nil {
245			seen := make(map[string]struct{}, len(matches))
246			normalized := make([]string, 0, len(matches))
247			for _, m := range matches {
248				n := normalizeImportPath(m)
249				if n == "" {
250					continue
251				}
252				if _, dup := seen[n]; dup {
253					continue
254				}
255				seen[n] = struct{}{}
256				normalized = append(normalized, n)
257			}
258			sort.Strings(normalized)
259			matches = normalized
260		}
261	
262		// cache a private copy of the name list
263		cached := make([]string, len(matches))
264		copy(cached, matches)
265		s.globs[pattern] = cached
266		return matches, nil
267	}
268	
269	// globWithReader enumerates matches using whichever optional glob
270	// capability the readers value exposes. An open-only reader cannot be
271	// enumerated, so a pattern has no matches there.
272	func globWithReader(readers FileReaders, pattern string) ([]string, error) {
273		if g, ok := readers.(fileGlobber); ok {
274			return g.Glob(pattern)
275		}
276		return nil, nil
277	}
278	
279	var driveLetterPattern = regexp.MustCompile(`^([A-Za-z]):[\\/]`)
280	
281	// normalizeImportPath canonicalizes a path used with FileReaders:
282	// Windows drive letters and backslashes are rewritten to forward
283	// slashes, the path is cleaned lexically, and a single leading slash is
284	// dropped so every name is tree-relative. Normalization never consults
285	// the working directory.
286	func normalizeImportPath(name string) string {
287		s := strings.ReplaceAll(name, "\\", "/")
288		if m := driveLetterPattern.FindStringSubmatch(s); m != nil {
289			s = m[1] + "/" + s[len(m[0]):]
290		}
291		s = path.Clean(s)
292		s = strings.TrimPrefix(s, "/")
293		if s == "." {
294			return ""
295		}
296		return s
297	}
298	
299	// isAbsolutePathPattern reports whether pattern names a location
300	// independently of the importing file's directory.
301	func isAbsolutePathPattern(pattern string) bool {
302		if strings.HasPrefix(pattern, "/") || strings.HasPrefix(pattern, "\\") {
303			return true
304		}
305		if driveLetterPattern.MatchString(pattern) {
306			return true
307		}
308		return filepath.IsAbs(pattern)
309	}
310	
311	// resolveVirtualImport joins a possibly-relative import pattern with
312	// the directory of the importing virtual file, normalizes the result,
313	// and rejects targets that escape the root of the file tree.
314	func resolveVirtualImport(importingFile, pattern string) (string, error) {
315		base := normalizeImportPath(importingFile)
316		patternNorm := normalizeImportPath(pattern)
317		if !isAbsolutePathPattern(pattern) {
318			patternNorm = path.Join(path.Dir(base), patternNorm)
319		}
320		if patternNorm == ".." || strings.HasPrefix(patternNorm, "../") {
321			return "", fmt.Errorf("import path %s resolves outside of the file tree", pattern)
322		}
323		return patternNorm, nil
324	}
