28	)
29	
30	// Parse parses the input just enough to group tokens, in
31	// order, by server block. No further parsing is performed.
32	// Server blocks are returned in the order in which they appear.
33	// Directives that do not appear in validDirectives will cause
34	// an error. If you do not want to check for valid directives,
35	// pass in nil instead.
36	//
37	// Environment variables in {$ENVIRONMENT_VARIABLE} notation
38	// will be replaced before parsing begins.
39	//
40	// If FileReaders are provided, every file named by an import
41	// directive is read through them for the duration of this call
42	// rather than from disk: the readers are the sole source of
43	// imported contents, and each file (and each glob result) is
44	// captured once, so replacing or reusing the readers between
45	// calls, or having them return different contents on a later
46	// open, can never mix versions into the result. The top-level
47	// input and every import therefore come from one snapshot.
48	// When no readers are given, imports resolve on the operating
49	// system filesystem as before.
50	//
51	// Parse keeps no state between calls: argument expansions,
52	// caches, snapshots, and errors from one parse can never be
53	// observed by another, even when calls run concurrently. A
54	// failed parse never returns usable blocks.
55	func Parse(filename string, input []byte, fileReaders ...FileReaders) ([]ServerBlock, error) {
56		// unfortunately, we must copy the input because parsing must
57		// remain a read-only operation, but we have to expand environment
58		// variables before we parse, which changes the underlying array (#4422)
59		inputCopy := make([]byte, len(input))
60		copy(inputCopy, input)
61	
62		tokens, err := allTokens(filename, inputCopy)
63		if err != nil {
64			return nil, err
65		}
66	
67		var readers FileReaders
68		if len(fileReaders) > 0 {
69			readers = fileReaders[0]
70		}
71	
72		p := parser{
73			Dispenser: NewDispenser(tokens),
74			imports:   newImportSource(readers),
75			importGraph: importGraph{
76				nodes: make(map[string]struct{}),
77				edges: make(adjacency),
78			},
79		}
80		blocks, err := p.parseAll()
81		if err != nil {
82			// never hand back a partially-expanded block list: a
83			// failed parse must not be usable as configuration
84			return nil, err
85		}
86		return blocks, nil
87	}
88	
89	// allTokens lexes the entire input, but does not parse it.
90	// It returns all the tokens from the input, unstructured
91	// and in order. It may mutate input as it expands env vars.
92	// Unclosed quotes are rejected because the resulting token
93	// stream would be ambiguous about where arguments end.
94	func allTokens(filename string, input []byte) ([]Token, error) {
95		return tokenizeStrict(replaceEnvVars(input), filename)
96	}
97	
98	// replaceEnvVars replaces all occurrences of environment variables.
99	// It mutates the underlying array and returns the updated slice.
100	func replaceEnvVars(input []byte) []byte {
101		var offset int
102		for {
103			begin := bytes.Index(input[offset:], spanOpen)
104			if begin < 0 {
105				break
106			}
107			begin += offset // make beginning relative to input, not offset
108			end := bytes.Index(input[begin+len(spanOpen):], spanClose)
109			if end < 0 {
110				break
111			}
112			end += begin + len(spanOpen) // make end relative to input, not begin
113	
114			// get the name; if there is no name, skip it
115			envString := input[begin+len(spanOpen) : end]
116			if len(envString) == 0 {
117				offset = end + len(spanClose)
118				continue
119			}
120	
121			// split the string into a key and an optional default
122			envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
123	
124			// do a lookup for the env var, replace with the default if not found
125			envVarValue, found := os.LookupEnv(envParts[0])
126			if !found && len(envParts) == 2 {
127				envVarValue = envParts[1]
128			}
129	
130			// get the value of the environment variable
131			// note that this causes one-level deep chaining
132			envVarBytes := []byte(envVarValue)
133	
134			// splice in the value
135			input = append(input[:begin],
136				append(envVarBytes, input[end+len(spanClose):]...)...)
137	
138			// continue at the end of the replacement
139			offset = begin + len(envVarBytes)
140		}
141		return input
142	}
143	
144	type parser struct {
145		*Dispenser
146		block           ServerBlock // current server block being parsed
147		eof             bool        // if we encounter a valid EOF in a hard place
148		definedSnippets map[string][]Token
149		nesting         int
150		imports         *importSource
151		importGraph     importGraph
152	}
153	
154	func (p *parser) parseAll() ([]ServerBlock, error) {
155		var blocks []ServerBlock
156	
157		for p.Next() {
158			err := p.parseOne()
159			if err != nil {
160				return blocks, err
161			}
162			if len(p.block.Keys) > 0 || len(p.block.Segments) > 0 {
163				blocks = append(blocks, p.block)
164			}
165			if p.nesting > 0 {
166				return blocks, p.EOFErr()
167			}
168		}
169	
170		return blocks, nil
171	}
172	
173	func (p *parser) parseOne() error {
174		p.block = ServerBlock{}
175		return p.begin()
176	}
177	
178	func (p *parser) begin() error {
179		if len(p.tokens) == 0 {
180			return nil
181		}
182	
183		err := p.addresses()
184		if err != nil {
185			return err
186		}
187	
188		if p.eof {
189			// this happens if the Caddyfile consists of only
190			// a line of addresses and nothing else
191			return nil
192		}
193	
194		if ok, name := p.isNamedRoute(); ok {
195			// we just need a dummy leading token to ease parsing later
196			nameToken := p.Token()
197			nameToken.Text = name
198	
199			// named routes only have one key, the route name
200			p.block.Keys = []Token{nameToken}
201			p.block.IsNamedRoute = true
202	
203			// get all the tokens from the block, including the braces
204			tokens, err := p.blockTokens(true)
205			if err != nil {
206				return err
207			}
208			tokens = append([]Token{nameToken}, tokens...)
209			p.block.Segments = []Segment{tokens}
210			return nil
211		}
212	
213		if ok, name := p.isSnippet(); ok {
214			if p.definedSnippets == nil {
215				p.definedSnippets = map[string][]Token{}
216			}
217			if _, found := p.definedSnippets[name]; found {
218				return p.Errf("redeclaration of previously declared snippet %s", name)
219			}
220			// consume all tokens til matched close brace
221			tokens, err := p.blockTokens(false)
222			if err != nil {
223				return err
224			}
225			// Just as we need to track which file the token comes from, we need to
226			// keep track of which snippet the token comes from. This is helpful
227			// in tracking import cycles across files/snippets by namespacing them.
228			// Without this, we end up with false-positives in cycle-detection.
229			for k, v := range tokens {
230				v.snippetName = name
231				tokens[k] = v
232			}
233			p.definedSnippets[name] = tokens
234			// empty block keys so we don't save this block as a real server.
235			p.block.Keys = nil
236			return nil
237		}
238	
239		return p.blockContents()
240	}
241	
242	func (p *parser) addresses() error {
243		var expectingAnother bool
244	
245		for {
246			value := p.Val()
247			token := p.Token()
248	
249			// Reject request matchers if trying to define them globally
250			if strings.HasPrefix(value, "@") {
251				return p.Errf("request matchers may not be defined globally, they must be in a site block; found %s", value)
252			}
253	
254			// Special case: import directive replaces tokens during parse-time
255			if value == "import" && p.isNewLine() {
256				err := p.doImport(0)
257				if err != nil {
258					return err
259				}
260				continue
261			}
262	
263			// Open brace definitely indicates end of addresses
264			if value == "{" {
265				if expectingAnother {
266					return p.Errf("Expected another address but had '%s' - check for extra comma", value)
267				}
268				// Mark this server block as being defined with braces.
269				// This is used to provide a better error message when
270				// the user may have tried to define two server blocks
271				// without having used braces, which are required in
272				// that case.
273				p.block.HasBraces = true
274				break
275			}
276	
277			// Users commonly forget to place a space between the address and the '{'
278			if strings.HasSuffix(value, "{") {
279				return p.Errf("Site addresses cannot end with a curly brace: '%s' - put a space between the token and the brace", value)
280			}
281	
282			if value != "" { // empty token possible if user typed ""
283				// Trailing comma indicates another address will follow, which
284				// may possibly be on the next line
285				if value[len(value)-1] == ',' {
286					value = value[:len(value)-1]
287					expectingAnother = true
288				} else {
289					expectingAnother = false // but we may still see another one on this line
290				}
291	
292				// If there's a comma here, it's probably because they didn't use a space
293				// between their two domains, e.g. "foo.com,bar.com", which would not be
294				// parsed as two separate site addresses.
295				if strings.Contains(value, ",") {
296					return p.Errf("Site addresses cannot contain a comma ',': '%s' - put a space after the comma to separate site addresses", value)
297				}
298	
299				// After the above, a comma surrounded by spaces would result
300				// in an empty token which we should ignore
301				if value != "" {
302					// Add the token as a site address
303					token.Text = value
304					p.block.Keys = append(p.block.Keys, token)
305				}
306			}
307	
308			// Advance token and possibly break out of loop or return error
309			hasNext := p.Next()
310			if expectingAnother && !hasNext {
311				return p.EOFErr()
312			}
313			if !hasNext {
314				p.eof = true
315				break // EOF
316			}
317			if !expectingAnother && p.isNewLine() {
318				break
319			}
320		}
321	
322		return nil
323	}
324	
325	func (p *parser) blockContents() error {
326		errOpenCurlyBrace := p.openCurlyBrace()
327		if errOpenCurlyBrace != nil {
328			// single-server configs don't need curly braces
329			p.cursor--
330		}
331	
332		err := p.directives()
333		if err != nil {
334			return err
335		}
336	
337		// only look for close curly brace if there was an opening
338		if errOpenCurlyBrace == nil {
339			err = p.closeCurlyBrace()
340			if err != nil {
341				return err
342			}
343		}
344	
345		return nil
346	}
347	
348	// directives parses through all the lines for directives
349	// and it expects the next token to be the first
350	// directive. It goes until EOF or closing curly brace
351	// which ends the server block.
352	func (p *parser) directives() error {
353		for p.Next() {
354			// end of server block
355			if p.Val() == "}" {
356				// p.nesting has already been decremented
357				break
358			}
359	
360			// special case: import directive replaces tokens during parse-time
361			if p.Val() == "import" {
362				err := p.doImport(1)
363				if err != nil {
364					return err
365				}
366				p.cursor-- // cursor is advanced when we continue, so roll back one more
367				continue
368			}
369	
370			// normal case: parse a directive as a new segment
371			// (a "segment" is a line which starts with a directive
372			// and which ends at the end of the line or at the end of
373			// the block that is opened at the end of the line)
374			if err := p.directive(); err != nil {
375				return err
376			}
377		}
378	
379		return nil
380	}
381	
382	// doImport swaps out the import directive and its argument
383	// (a total of 2 tokens) with the tokens in the specified file
384	// or globbing pattern. When the function returns, the cursor
385	// points at the first imported token, which sits exactly where
386	// the import directive used to.
387	func (p *parser) doImport(nesting int) error {
388		// remember where the import statement started, so the splice
389		// never depends on how many argument or block tokens were read
390		importStart := p.cursor
391		// capture the import directive itself: a failure (cycle, missing
392		// file, bad placeholder) is reported at this position, which is
393		// stable no matter how far token reading advanced the cursor
394		importTok := p.Token()
395	
396		// syntax checks
397		if !p.NextArg() {
398			return p.ArgErr()
399		}
400		importPattern := p.Val()
401		if importPattern == "" {
402			return p.Err("Import requires a non-empty filepath")
403		}
404	
405		// grab remaining args as full tokens so that arguments keep
406		// their exact bytes and quoting: empty arguments, spaces, and
407		// quotes must never be re-tokenized during expansion
408		argTokens := p.RemainingArgsAsTokens()
409	
410		// grab all the tokens (if it exists) from within a block that follows the import
411		var blockTokens []Token
412		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
413			blockTokens = append(blockTokens, p.Token())
414		}
415		// initialize with size 1
416		blockMapping := make(map[string][]Token, 1)
417		if len(blockTokens) > 0 {
418			// use such tokens to create a new dispenser, and then use it to parse each block
419			bd := NewDispenser(blockTokens)
420	
421			// one iteration processes one sub-block inside the import
422			for bd.Next() {
423				currentMappingKey := bd.Val()
424	
425				if currentMappingKey == "{" {
426					return p.Err("anonymous blocks are not supported")
427				}
428	
429				// load up all arguments (if there even are any)
430				currentMappingTokens := bd.RemainingArgsAsTokens()
431	
432				// load up the entire block
433				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
434					currentMappingTokens = append(currentMappingTokens, bd.Token())
435				}
436	
437				blockMapping[currentMappingKey] = currentMappingTokens
438			}
439		}
440	
441		// everything before the import statement stays exactly where it was
442		tokensBefore := p.tokens[:importStart]
443		tokensAfter := p.tokens[p.cursor+1:]
444		var importedTokens []Token
445		var nodes []string
446	
447		// first check snippets. That is a simple, non-recursive replacement
448		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
449			// deep-copy the stored definition so repeated imports, and the
450			// annotations appended below, can never mutate one another or
451			// the snippet table (see the same-file, different-branch case)
452			stored := p.definedSnippets[importPattern]
453			importedTokens = make([]Token, len(stored))
454			for i := range stored {
455				importedTokens[i] = stored[i].Clone()
456			}
457			if len(importedTokens) > 0 {
458				// just grab the first one
459				nodes = append(nodes, fmt.Sprintf("%s:%s", importedTokens[0].File, importedTokens[0].snippetName))
460			}
461		} else {
462			fileTokens, fileNodes, err := p.resolveFileImports(importPattern)
463			if err != nil {
464				return err
465			}
466			importedTokens = fileTokens
467			nodes = fileNodes
468		}
469	
470		nodeName := p.File()
471		if p.Token().snippetName != "" {
472			nodeName += fmt.Sprintf(":%s", p.Token().snippetName)
473		}
474		p.importGraph.addNode(nodeName)
475		p.importGraph.addNodes(nodes)
476		if err := p.importGraph.addEdges(nodeName, nodes); err != nil {
477			p.importGraph.removeNodes(nodes)
478			// report the cycle at the import statement that completed it,
479			// with its import chain, so the failure location is stable
480			return wrapAtToken(importTok, err)
481		}
482	
483		tokensCopy := make([]Token, 0, len(importedTokens))
484	
485		var (
486			maybeSnippet   bool
487			maybeSnippetId bool
488			index          int
489		)
490	
491		// Expand argument placeholders for this one layer only: only the
492		// arguments given to THIS import statement are visible among these
493		// tokens. A nested import reached from within (a named snippet or
494		// another file) is expanded later, when the parser reaches the
495		// nested statement, with that layer's own arguments in scope, so
496		// values passed by an outer layer never leak across layers.
497		//
498		// golang for range slice return a copy of value
499		// similarly, append also copy value
500		for i, token := range importedTokens {
501			// update the token's imports to refer to import directive filename, line number and snippet name if there is one
502			if token.snippetName != "" {
503				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName))
504			} else {
505				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import)", p.File(), p.Line()))
506			}
507	
508			// naive way of determine snippets, as snippets definition can only follow name + block
509			// format, won't check for nesting correctness or any other error, that's what parser does.
510			if !maybeSnippet && nesting == 0 {
511				// first of the line
512				if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
513					index = 0
514				} else {
515					index++
516				}
517	
518				if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
519					maybeSnippetId = true
520				}
521			}
522	
523			switch token.Text {
524			case "{":
525				nesting++
526				if index == 1 && maybeSnippetId && nesting == 1 {
527					maybeSnippet = true
528					maybeSnippetId = false
529				}
530			case "}":
531				nesting--
532				if nesting == 0 && maybeSnippet {
533					maybeSnippet = false
534				}
535			}
536			// if it is {block}, we substitute with all tokens in the block
537			// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
538			var blockTokensToAdd []Token
539			foundBlockDirective := false
540			switch {
541			case token.Text == "{block}":
542				foundBlockDirective = true
543				blockTokensToAdd = blockTokens
544			case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
545				foundBlockDirective = true
546				// {blocks.foo.bar} will be extracted to key `foo.bar`
547				blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
548				val, ok := blockMapping[blockKey]
549				if ok {
550					blockTokensToAdd = val
551				}
552			}
553	
554			if foundBlockDirective {
555				if maybeSnippet {
556					tokensCopy = append(tokensCopy, token)
557				} else {
558					tokensCopy = append(tokensCopy, blockTokensToAdd...)
559				}
560				continue
561			}
562	
563			if maybeSnippet {
564				// placeholders inside a snippet definition are not
565				// expanded until the snippet itself is imported
566				tokensCopy = append(tokensCopy, token)
567				continue
568			}
569	
570			replaced, err := substituteImportArgs(token, argTokens)
571			if err != nil {
572				return err
573			}
574			tokensCopy = append(tokensCopy, replaced...)
575		}
576	
577		// splice the imported tokens in the place of the import statement;
578		// the cursor lands on the first imported token so parsing simply
579		// continues into the expansion
580		p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
581		p.cursor = importStart
582	
583		return nil
584	}
585	
586	// resolveFileImports turns the import pattern into the tokens of
587	// every matching file, reading from the configured FileReaders for the
588	// call or from disk otherwise.
589	func (p *parser) resolveFileImports(importPattern string) ([]Token, []string, error) {
590		if !p.imports.onDisk() {
591			return p.resolveReaderImports(importPattern)
592		}
593		return p.resolveDiskImports(importPattern)
594	}
595	
596	// resolveReaderImports resolves an import pattern entirely through the
597	// call's FileReaders snapshot.
598	func (p *parser) resolveReaderImports(importPattern string) ([]Token, []string, error) {
599		importingFile := normalizeImportPath(p.Dispenser.File())
600		globPattern, err := resolveVirtualImport(importingFile, importPattern)
601		if err != nil {
602			return nil, nil, p.Errf("%v", err)
603		}
604	
605		hasMeta := strings.ContainsAny(globPattern, "*?[")
606		var matches []string
607		if hasMeta {
608			// bound pathological patterns just like the on-disk path
609			// (issue #2096)
610			if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
611				(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
612				return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
613			}
614			matches, err = p.imports.glob(globPattern)
615			if err != nil {
616				return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
617			}
618		} else {
619			matches = []string{globPattern}
620		}
621	
622		if len(matches) == 0 {
623			if hasMeta {
624				// a glob with no matches keeps the historical success
625				// semantics: it simply contributes no tokens
626				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
627				return nil, nil, nil
628			}
629			return nil, nil, p.Errf("File to import not found: %s", importPattern)
630		}
631		matches = skipDotfiles(globPattern, matches)
632	
633		var importedTokens []Token
634		for _, importFile := range matches {
635			newTokens, err := p.readImportFile(importFile)
636			if err != nil {
637				return nil, nil, err
638			}
639			importedTokens = append(importedTokens, newTokens...)
640		}
641		return importedTokens, matches, nil
642	}
643	
644	// resolveDiskImports preserves the on-disk behavior: patterns are
645	// resolved relative to the importing token's file (issue #867),
646	// globs are bounded against pathological expansion (issue #2096),
647	// and dotfiles are skipped for directory-star globs (issue #5295).
648	func (p *parser) resolveDiskImports(importPattern string) ([]Token, []string, error) {
649		// make path relative to the file of the _token_ being processed rather
650		// than current working directory (issue #867) and then use glob to get
651		// list of matching filenames
652		absFile, err := caddy.FastAbs(p.Dispenser.File())
653		if err != nil {
654			return nil, nil, p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
655		}
656	
657		var matches []string
658		var globPattern string
659		if !filepath.IsAbs(importPattern) {
660			globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
661		} else {
662			globPattern = importPattern
663		}
664		if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
665			(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
666			// See issue #2096 - a pattern with many glob expansions can hang for too long
667			return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
668		}
669		matches, err = p.imports.glob(globPattern)
670		if err != nil {
671			return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
672		}
673		if len(matches) == 0 {
674			if strings.ContainsAny(globPattern, "*?[]") {
675				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
676				return nil, nil, nil
677			}
678			return nil, nil, p.Errf("File to import not found: %s", importPattern)
679		}
680		matches = skipDotfiles(globPattern, matches)
681	
682		var importedTokens []Token
683		for _, importFile := range matches {
684			newTokens, err := p.readImportFile(importFile)
685			if err != nil {
686				return nil, nil, err
687			}
688			importedTokens = append(importedTokens, newTokens...)
689		}
690		return importedTokens, matches, nil
691	}
692	
693	// skipDotfiles drops dotfile matches when the final pattern segment
694	// is a bare star, mirroring the historical glob behavior.
695	func skipDotfiles(globPattern string, matches []string) []string {
696		sep := "/"
697		if strings.Contains(globPattern, string(filepath.Separator)) {
698			sep = string(filepath.Separator)
699		}
700		segGlobPattern := strings.Split(globPattern, sep)
701		if !strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
702			return matches
703		}
704		var filtered []string
705		for _, m := range matches {
706			seg := strings.Split(m, sep)
707			if strings.HasPrefix(seg[len(seg)-1], ".") {
708				continue
709			}
710			filtered = append(filtered, m)
711		}
712		return filtered
713	}
714	
715	// readImportFile lexes the individual file identified by importFile
716	// through the call's snapshot and returns its tokens. Token file names
717	// are normalized to stable paths: the absolute on-disk path when
718	// reading disk (issue #1892), and the normalized virtual path when
719	// reading through FileReaders, neither of which depends on the working
720	// directory.
721	func (p *parser) readImportFile(importFile string) ([]Token, error) {
722		input, err := p.imports.readFile(importFile)
723		if err != nil {
724			if errors.Is(err, errImportIsDir) {
725				return nil, p.Errf("Could not import %s: is a directory", importFile)
726			}
727			return nil, p.Errf("Could not import %s: %v", importFile, err)
728		}
729	
730		// only warning in case of empty files
731		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
732			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
733			return []Token{}, nil
734		}
735	
736		importedTokens, err := allTokens(importFile, input)
737		if err != nil {
738			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
739		}
740	
741		filename := importFile
742		if p.imports.onDisk() {
743			// Tack the absolute path onto these tokens on disk so errors
744			// show the imported file's name reliably (issue #1892)
745			absName, absErr := caddy.FastAbs(importFile)
746			if absErr != nil {
747				return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, absErr)
748			}
749			filename = absName
750		}
751		for i := range importedTokens {
752			importedTokens[i].File = filename
753		}
754	
755		return importedTokens, nil
756	}
757	
758	// directive collects tokens until the directive's scope
759	// closes (either end of line or end of curly brace block).
760	// It expects the currently-loaded token to be a directive
761	// (or } that ends a server block). The collected tokens
762	// are loaded into the current server block for later use
763	// by directive setup functions.
764	func (p *parser) directive() error {
765		// a segment is a list of tokens associated with this directive
766		var segment Segment
767	
768		// the directive itself is appended as a relevant token
769		segment = append(segment, p.Token())
770	
771		for p.Next() {
772			if p.Val() == "{" {
773				p.nesting++
774				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
775					return p.Err("Unexpected next token after '{' on same line")
776				}
777				if p.isNewLine() {
778					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
779				}
780			} else if p.Val() == "{}" {
781				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
782					return p.Err("Unexpected '{}' at end of line")
783				}
784			} else if p.isNewLine() && p.nesting == 0 {
785				p.cursor-- // read too far
786				break
787			} else if p.Val() == "}" && p.nesting > 0 {
788				p.nesting--
789			} else if p.Val() == "}" && p.nesting == 0 {
790				return p.Err("Unexpected '}' because no matching opening brace")
791			} else if p.Val() == "import" && p.isNewLine() {
792				if err := p.doImport(1); err != nil {
793					return err
794				}
795				p.cursor-- // cursor is advanced when we continue, so roll back one more
796				continue
797			}
798	
799			segment = append(segment, p.Token())
800		}
801	
802		p.block.Segments = append(p.block.Segments, segment)
803	
804		if p.nesting > 0 {
805			return p.EOFErr()
806		}
807	
808		return nil
809	}
810	
811	// openCurlyBrace expects the current token to be an
812	// opening curly brace. This acts like an assertion
813	// because it returns an error if the token is not
814	// an opening brace. It does NOT advance the token.
815	func (p *parser) openCurlyBrace() error {
816		if p.Val() != "{" {
817			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
818				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
819			}
820			return p.SyntaxErr("{")
821		}
822		return nil
823	}
824	
825	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
826		if p.Val() != "import" || len(p.block.Keys) == 0 {
827			return false
828		}
829	
830		for _, key := range p.block.Keys {
831			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
832				return false
833			}
834		}
835	
836		return true
837	}
838	
839	// closeCurlyBrace expects the current token to be
840	// a closing curly brace. This acts like an assertion
841	// because it returns an error if the token is not
842	// a closing curly brace. It does NOT advance the token.
843	func (p *parser) closeCurlyBrace() error {
844		if p.Val() != "}" {
845			return p.SyntaxErr("}")
846		}
847		return nil
848	}
849	
850	func (p *parser) isNamedRoute() (bool, string) {
851		keys := p.block.Keys
852		// A named route block is a single key with parens, prefixed with &.
853		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
854			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
855		}
856		return false, ""
857	}
858	
859	func (p *parser) isSnippet() (bool, string) {
860		keys := p.block.Keys
861		// A snippet block is a single key with parens. Nothing else qualifies.
862		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
863			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
864		}
865		return false, ""
866	}
867	
868	// read and store everything in a block for later replay.
869	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
870		// block must have curlies.
871		err := p.openCurlyBrace()
872		if err != nil {
873			return nil, err
874		}
875		nesting := 1 // count our own nesting
876		tokens := []Token{}
877		if retainCurlies {
878			tokens = append(tokens, p.Token())
879		}
880		for p.Next() {
881			if p.Val() == "}" {
882				nesting--
883				if nesting == 0 {
884					if retainCurlies {
885						tokens = append(tokens, p.Token())
886					}
887					break
888				}
889			}
890			if p.Val() == "{" {
891				nesting++
892			}
893			tokens = append(tokens, p.tokens[p.cursor])
894		}
895		// make sure we're matched up
896		if nesting != 0 {
897			return nil, p.SyntaxErr("}")
898		}
899		return tokens, nil
900	}
901	
902	// ServerBlock associates any number of keys from the
903	// head of the server block with tokens, which are
904	// grouped by segments.
905	type ServerBlock struct {
906		HasBraces    bool
907		Keys         []Token
908		Segments     []Segment
909		IsNamedRoute bool
910	}
911	
912	func (sb ServerBlock) GetKeysText() []string {
913		res := make([]string, 0, len(sb.Keys))
914		for _, k := range sb.Keys {
915			res = append(res, k.Text)
916		}
917		return res
918	}
919	
920	// DispenseDirective returns a dispenser that contains
921	// all the tokens in the server block.
922	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
923		var tokens []Token
924		for _, seg := range sb.Segments {
925			if len(seg) > 0 && seg[0].Text == dir {
926				tokens = append(tokens, seg...)
927			}
928		}
929		return NewDispenser(tokens)
930	}
931	
932	// Segment is a list of tokens which begins with a directive
933	// and ends at the end of the directive (either at the end of
934	// the line, or at the end of a block it opens).
935	type Segment []Token
936	
937	// Directive returns the directive name for the segment.
938	// The directive name is the text of the first token.
939	func (s Segment) Directive() string {
940		if len(s) > 0 {
941			return s[0].Text
942		}
943		return ""
944	}
945	
946	// spanOpen and spanClose are used to bound spans that
947	// contain the name of an environment variable.
948	var (
949		spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
950		envVarDefaultDelimiter = ":"
951	)
952	
953	// wrapAtToken reports err at the source location of tok (an import
954	// directive), including its import chain. It is used for failures that
955	// are detected after the cursor has moved on (such as import cycles)
956	// so the first failing statement keeps a stable, readable position.
957	func wrapAtToken(tok Token, err error) error {
958		if len(tok.imports) > 0 {
959			return fmt.Errorf("%w, at %s:%d import chain ['%s']",
960				err, tok.File, tok.Line, strings.Join(tok.imports, "','"))
961		}
962		return fmt.Errorf("%w, at %s:%d", err, tok.File, tok.Line)
963	}
