23	// argsPlaceholderKind enumerates the argument placeholder forms
24	// recognized by the import expansion.
25	type argsPlaceholderKind int
26	
27	const (
28		argsSingle   argsPlaceholderKind = iota // {args[N]} (or deprecated {args.N})
29		argsVariadic                            // {args[a:b]}
30	)
