32	// argsPlaceholder describes a parsed argument placeholder.
33	type argsPlaceholder struct {
34		kind       argsPlaceholderKind
35		start      int // inclusive start index (single and variadic)
36		end        int // exclusive end index (variadic only); -1 means open-ended
37		deprecated bool
38	}
