40	// parseArgsPlaceholder parses body, the text between the braces of a
41	// placeholder (for example "args[0]" or "args[1:3]"), and reports
42	// whether it is a well-formed argument placeholder. A body that is
43	// clearly meant to be one but has an illegal index is reported with
44	// ok == true and a non-nil err, so callers can reject the parse
45	// instead of silently leaving the text untouched.
46	func parseArgsPlaceholder(body string) (argsPlaceholder, bool, error) {
47		if strings.HasPrefix(body, "args[") && strings.HasSuffix(body, "]") {
48			inner := body[len("args[") : len(body)-len("]")]
49			if inner == "" {
50				return argsPlaceholder{}, true, fmt.Errorf("placeholder {args[]} cannot have an empty index")
51			}
52	
53			rawStart, rawEnd, hasRange := strings.Cut(inner, ":")
54			if !hasRange {
55				index, err := parsePlaceholderIndex(rawStart)
56				if err != nil {
57					return argsPlaceholder{kind: argsSingle}, true, err
58				}
59				return argsPlaceholder{kind: argsSingle, start: index, end: index + 1}, true, nil
60			}
61	
62			// more than one colon is never a valid index range
63			if strings.Count(inner, ":") > 1 {
64				return argsPlaceholder{kind: argsVariadic}, true, fmt.Errorf("variadic placeholder {%s} has an invalid index range", body)
65			}
66	
67			ph := argsPlaceholder{kind: argsVariadic}
68			if rawStart == "" {
69				ph.start = 0
70			} else {
71				index, err := parsePlaceholderIndex(rawStart)
72				if err != nil {
73					return argsPlaceholder{kind: argsVariadic}, true, err
74				}
75				ph.start = index
76			}
77			if rawEnd == "" {
78				// open-ended ranges are bounded by the argument count later
79				ph.end = -1
80			} else {
81				index, err := parsePlaceholderIndex(rawEnd)
82				if err != nil {
83					return argsPlaceholder{kind: argsVariadic}, true, err
84				}
85				ph.end = index
86			}
87			return ph, true, nil
88		}
89	
90		// TODO: Remove the deprecated {args.*} placeholder support at
91		// some point in the future.
92		if strings.HasPrefix(body, "args.") && body != "args." {
93			index, err := parsePlaceholderIndex(strings.TrimPrefix(body, "args."))
94			if err != nil {
95				return argsPlaceholder{deprecated: true}, true, err
96			}
97			return argsPlaceholder{kind: argsSingle, start: index, end: index + 1, deprecated: true}, true, nil
98		}
99	
100		return argsPlaceholder{}, false, nil
101	}
102	
103	// parsePlaceholderIndex parses a single non-negative argument index.
104	func parsePlaceholderIndex(raw string) (int, error) {
105		index, err := strconv.Atoi(raw)
106		if err != nil || index < 0 {
107			return 0, fmt.Errorf("invalid argument index %q", raw)
108		}
109		return index, nil
110	}
111	
112	// looksLikeArgsPlaceholder reports whether body, the contents of a
113	// brace pair, was clearly intended as an argument placeholder but is
114	// malformed. Such text is an error instead of being kept verbatim.
115	func looksLikeArgsPlaceholder(body string) bool {
116		return body == "args" || body == "args." ||
117			strings.HasPrefix(body, "args[") || strings.HasPrefix(body, "args.")
118	}
119	
120	// wholeTokenPlaceholder parses text expecting it to contain exactly
121	// one argument placeholder and nothing else. A token made of several
122	// adjacent (or malformed) placeholders is not a whole-token match; the
123	// slow-path scanner decides its fate instead.
124	func wholeTokenPlaceholder(text string) (argsPlaceholder, bool, error) {
125		if len(text) < 2 || text[0] != '{' || text[len(text)-1] != '}' {
126			return argsPlaceholder{}, false, nil
127		}
128		body := text[1 : len(text)-1]
129		// one placeholder cannot itself contain braces, so a token
130		// holding several adjacent placeholders is never a whole match
131		// and is left for the scanner
132		if strings.ContainsAny(body, "{}") {
133			return argsPlaceholder{}, false, nil
134		}
135		ph, ok, err := parseArgsPlaceholder(body)
136		if !ok {
137			return argsPlaceholder{}, false, nil
138		}
139		return ph, true, err
140	}
141	
142	// substituteImportArgs expands argument placeholders in one imported
143	// token. A whole-token placeholder is replaced with the argument
144	// token itself (so arguments containing spaces or quotes stay a
145	// single token, with their quoting intact); a placeholder embedded
146	// in surrounding text is substituted in place and can never cause
147	// re-tokenization.
148	//
149	// Ordinary braces, adjacent literal text, and braces escaped with a
150	// backslash are preserved verbatim. Malformed placeholders, indices
151	// out of range, and variadic placeholders embedded in other text are
152	// reported as errors, located at the imported token.
153	func substituteImportArgs(token Token, argTokens []Token) ([]Token, error) {
154		text := token.Text
155	
156		// fast path: the token is a single placeholder on its own
157		if ph, ok, err := wholeTokenPlaceholder(text); ok {
158			if err != nil {
159				return nil, importArgsErr(token, err.Error())
160			}
161			if ph.kind == argsSingle {
162				if ph.start >= len(argTokens) {
163					return nil, importArgsErr(token,
164						fmt.Sprintf("placeholder {args[%d]} is out of range: only %d argument(s) were given to the import", ph.start, len(argTokens)))
165				}
166				return []Token{positionArgToken(argTokens[ph.start], token)}, nil
167			}
168	
169			// variadic: validate the range against the available args
170			start, end, err := boundVariadic(ph, len(argTokens), text)
171			if err != nil {
172				return nil, importArgsErr(token, err.Error())
173			}
174			out := make([]Token, 0, end-start)
175			for _, arg := range argTokens[start:end] {
176				out = append(out, positionArgToken(arg, token))
177			}
178			return out, nil
179		}
180	
181		// slow path: scan the token for embedded placeholders
182		var sb strings.Builder
183		sb.Grow(len(text))
184		for i := 0; i < len(text); {
185			// escaped braces are literal braces; the escaping backslash
186			// is consumed so the brace is never re-expanded
187			if text[i] == '\\' && i+1 < len(text) && (text[i+1] == '{' || text[i+1] == '}') {
188				sb.WriteByte(text[i+1])
189				i += 2
190				continue
191			}
192	
193			if text[i] != '{' {
194				sb.WriteByte(text[i])
195				i++
196				continue
197			}
198	
199			closeRel := strings.IndexByte(text[i+1:], '}')
200			if closeRel < 0 {
201				// unmatched opening brace: the rest is ordinary text
202				sb.WriteString(text[i:])
203				break
204			}
205			end := i + 1 + closeRel
206			body := text[i+1 : end]
207	
208			ph, isArgs, parseErr := parseArgsPlaceholder(body)
209			if !isArgs {
210				if looksLikeArgsPlaceholder(body) {
211					return nil, importArgsErr(token, fmt.Sprintf("invalid argument placeholder {%s}", body))
212				}
213				// this brace pair is not an args placeholder (for
214				// example a JSON object), but an args placeholder may
215				// still be nested inside it; emit just the opening
216				// brace and rescan its contents
217				sb.WriteByte('{')
218				i++
219				continue
220			}
221			if parseErr != nil {
222				return nil, importArgsErr(token, parseErr.Error())
223			}
224			if ph.kind == argsVariadic {
225				return nil, importArgsErr(token, fmt.Sprintf("variadic placeholder {%s} must be a token on its own", body))
226			}
227			if ph.start >= len(argTokens) {
228				indexText := strconv.Itoa(ph.start)
229				if ph.deprecated {
230					return nil, importArgsErr(token,
231						fmt.Sprintf("placeholder {args.%s} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
232				}
233				return nil, importArgsErr(token,
234					fmt.Sprintf("placeholder {args[%s]} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
235			}
236	
237			// substitute only the argument's text, in place; quoting
238			// belongs to the surrounding token and is left untouched
239			sb.WriteString(argTokens[ph.start].Text)
240			i = end + 1
241		}
242	
243		out := token
244		out.Text = sb.String()
245		return []Token{out}, nil
246	}
247	
248	// boundVariadic resolves an open-ended variadic range and validates
249	// it against the number of available arguments.
250	func boundVariadic(ph argsPlaceholder, argCount int, text string) (int, int, error) {
251		start := ph.start
252		end := ph.end
253		if end == -1 {
254			end = argCount
255		}
256		if start > end {
257			return 0, 0, fmt.Errorf("variadic placeholder %s has a start index greater than its end index", text)
258		}
259		if end > argCount {
260			return 0, 0, fmt.Errorf("variadic placeholder %s is out of range: only %d argument(s) were given to the import", text, argCount)
261		}
262		return start, end, nil
263	}
264	
265	// positionArgToken returns a copy of a placeholder token carrying an
266	// argument's value. Location and import provenance stay attached to
267	// where the placeholder was written (so line adjacency and error
268	// locations are stable through nested imports), while the argument's
269	// exact text and quoting are preserved without re-tokenization.
270	func positionArgToken(arg, placeholder Token) Token {
271		t := placeholder.Clone()
272		t.Text = arg.Text
273		t.wasQuoted = arg.wasQuoted
274		t.quoteClosed = arg.quoteClosed
275		t.heredocMarker = arg.heredocMarker
276		return t
277	}
278	
279	// importArgsErr builds a parse error for a placeholder problem,
280	// pointing at the file and line where the placeholder was written.
281	func importArgsErr(token Token, msg string) error {
282		if len(token.imports) > 0 {
283			return fmt.Errorf("%s, at %s:%d import chain ['%s']",
284				msg, token.File, token.Line, strings.Join(token.imports, "','"))
285		}
286		return fmt.Errorf("%s, at %s:%d", msg, token.File, token.Line)
287	}
288	
289	// parseVariadic determines if the token is a variadic placeholder,
290	// and if so, determines the index range (start/end) of args to use.
291	// Returns a boolean signaling whether a variadic placeholder was found,
292	// and the start and end indices.
293	//
294	// Deprecated: retained for the unit-level predicate checks; expansion
295	// goes through substituteImportArgs, which also rejects malformed
296	// placeholders and out-of-range indices as hard parse errors.
297	func parseVariadic(token Token, argCount int) (bool, int, int) {
298		ph, ok, err := wholeTokenPlaceholder(token.Text)
299		if err != nil || !ok || ph.kind != argsVariadic {
300			return false, 0, 0
301		}
302		start, end, err := boundVariadic(ph, argCount, token.Text)
303		if err != nil {
304			return false, 0, 0
305		}
306		return true, start, end
307	}
308

