14	
15	package caddyfile
16	
17	import (
18		"bufio"
19		"bytes"
20		"errors"
21		"fmt"
22		"io"
23		"regexp"
24		"strings"
25		"unicode"
26	)
27	
28	// errUnclosedQuote is returned by the lexer when a quoted token runs
29	// into the end of the input without a closing quote. Callers may use
30	// errors.Is to detect it and attach the source location.
31	var errUnclosedQuote = errors.New("unclosed quote")
32	
33	type (
34		// lexer is a utility which can get values, token by
35		// token by token, from a Reader. A token is a word, and tokens
36		// are separated by whitespace. A word can be enclosed
37		// in quotes if it contains whitespace.
38		lexer struct {
39			reader       *bufio.Reader
40			token        Token
41			file         string
42			line         int
43			skippedLines int
44			// strict, when true, causes an unclosed quote to be an
45			// error instead of being tolerated up to EOF.
46			strict bool
47		}
48	
49		// Token represents a single parsable unit.
50		Token struct {
51			File          string
52			imports       []string
53			Line          int
54			Text          string
55			wasQuoted     rune // enclosing quote character, if any
56			quoteClosed   bool // whether the enclosing quote was closed
57			heredocMarker string
58			snippetName   string
59		}
60	)
61	
62	// Tokenize takes bytes as input and lexes it into
63	// a list of tokens that can be parsed as a Caddyfile.
64	// Also takes a filename to fill the token's File as
65	// the source of the tokens, which is important to
66	// determine relative paths for `import` directives.
67	func Tokenize(input []byte, filename string) ([]Token, error) {
68		return tokenize(input, filename, false)
69	}
70	
71	// tokenizeStrict is like Tokenize, except an unclosed
72	// quote is reported as an error instead of being
73	// tolerated up to EOF.
74	func tokenizeStrict(input []byte, filename string) ([]Token, error) {
75		return tokenize(input, filename, true)
76	}
77	
78	func tokenize(input []byte, filename string, strict bool) ([]Token, error) {
79		l := lexer{file: filename, strict: strict}
80		if err := l.load(bytes.NewReader(input)); err != nil {
81			return nil, err
82		}
83		var tokens []Token
84		for {
85			found, err := l.next()
86			if err != nil {
87				return nil, err
88			}
89			if !found {
90				break
91			}
92			l.token.File = filename
93			tokens = append(tokens, l.token)
94		}
95		return tokens, nil
96	}
97	
98	// load prepares the lexer to scan an input for tokens.
99	// It discards any leading byte order mark.
100	func (l *lexer) load(input io.Reader) error {
101		l.reader = bufio.NewReader(input)
102		l.line = 1
103	
104		// discard byte order mark, if present
105		firstCh, _, err := l.reader.ReadRune()
106		if err != nil {
107			return err
108		}
109		if firstCh != 0xFEFF {
110			err := l.reader.UnreadRune()
111			if err != nil {
112				return err
113			}
114		}
115	
116		return nil
117	}
118	
119	// next loads the next token into the lexer.
120	// A token is delimited by whitespace, unless
121	// the token starts with a quotes character (")
122	// in which case the token goes until the closing
123	// quotes (the enclosing quotes are not included).
124	// Inside quoted strings, quotes may be escaped
125	// with a preceding \ character. No other chars
126	// may be escaped. The rest of the line is skipped
127	// if a "#" character is read in. Returns true if
128	// a token was loaded; false otherwise.
129	func (l *lexer) next() (bool, error) {
130		var val []rune
131		var comment, quoted, btQuoted, inHeredoc, heredocEscaped, escaped bool
132		var heredocMarker string
133	
134		makeToken := func(quoted rune, closed bool) bool {
135			l.token.Text = string(val)
136			l.token.wasQuoted = quoted
137			l.token.quoteClosed = closed
138			l.token.heredocMarker = heredocMarker
139			return true
140		}
141	
142		for {
143			// Read a character in; if err then if we had
144			// read some characters, make a token. If we
145			// reached EOF, then no more tokens to read.
146			// If no EOF, then we had a problem.
147			ch, _, err := l.reader.ReadRune()
148			if err != nil {
149				if inHeredoc && len(val) > 0 {
150					return false, fmt.Errorf("incomplete heredoc <<%s on line #%d, expected ending marker %s", heredocMarker, l.line+l.skippedLines, heredocMarker)
151				}
152	
153				if (quoted || btQuoted) && l.strict {
154					quoteCh := byte('"')
155					if btQuoted {
156						quoteCh = '`'
157					}
158					return false, fmt.Errorf("%w %c opened on line #%d, at %s:%d",
159						errUnclosedQuote, quoteCh, l.token.Line, l.file, l.line+l.skippedLines)
160				}
161	
162				if len(val) > 0 {
163					return makeToken(0, false), nil
164				}
165				if err == io.EOF {
166					return false, nil
167				}
168				return false, err
169			} // detect whether we have the start of a heredoc
170			if (!quoted && !btQuoted) && (!inHeredoc && !heredocEscaped) &&
171				len(val) > 1 && string(val[:2]) == "<<" {
172				// a space means it's just a regular token and not a heredoc
173				if ch == ' ' {
174					return makeToken(0, false), nil
175				}
176	
177				// skip CR, we only care about LF
178				if ch == '\r' {
179					continue
180				}
181	
182				// after hitting a newline, we know that the heredoc marker
183				// is the characters after the two << and the newline.
184				// we reset the val because the heredoc is syntax we don't
185				// want to keep.
186				if ch == '\n' {
187					if len(val) == 2 {
188						return false, fmt.Errorf("missing opening heredoc marker on line #%d; must contain only alphanumeric characters, dashes and underscores; got empty string", l.line)
189					}
190	
191					// check if there's too many <
192					if string(val[:3]) == "<<<" {
193						return false, fmt.Errorf("too many '<' for heredoc on line #%d; only use two, for example <<END", l.line)
194					}
195	
196					heredocMarker = string(val[2:])
197					if !heredocMarkerRegexp.Match([]byte(heredocMarker)) {
198						return false, fmt.Errorf("heredoc marker on line #%d must contain only alphanumeric characters, dashes and underscores; got '%s'", l.line, heredocMarker)
199					}
200	
201					inHeredoc = true
202					l.skippedLines++
203					val = nil
204					continue
205				}
206				val = append(val, ch)
207				continue
208			}
209	
210			// if we're in a heredoc, all characters are read as-is
211			if inHeredoc {
212				val = append(val, ch)
213	
214				if ch == '\n' {
215					l.skippedLines++
216				}
217	
218				// check if we're done, i.e. that the last few characters are the marker
219				if len(val) >= len(heredocMarker) && heredocMarker == string(val[len(val)-len(heredocMarker):]) {
220					// set the final value
221					val, err = l.finalizeHeredoc(val, heredocMarker)
222					if err != nil {
223						return false, err
224					}
225	
226					// set the line counter, and make the token
227					l.line += l.skippedLines
228					l.skippedLines = 0
229					return makeToken('<', true), nil
230				}
231	
232				// stay in the heredoc until we find the ending marker
233				continue
234			}
235	
236			// track whether we found an escape '\' for the next
237			// iteration to be contextually aware
238			if !escaped && !btQuoted && ch == '\\' {
239				escaped = true
240				continue
241			}
242	
243			if quoted || btQuoted {
244				if quoted && escaped {
245					// all is literal in quoted area,
246					// so only escape quotes
247					if ch != '"' {
248						val = append(val, '\\')
249					}
250					escaped = false
251				} else {
252					if (quoted && ch == '"') || (btQuoted && ch == '`') {
253						return makeToken(ch, true), nil
254					}
255				}
256				// allow quoted text to wrap continue on multiple lines
257				if ch == '\n' {
258					l.line += 1 + l.skippedLines
259					l.skippedLines = 0
260				}
261				// collect this character as part of the quoted token
262				val = append(val, ch)
263				continue
264			}
265	
266			if unicode.IsSpace(ch) {
267				// ignore CR altogether, we only actually care about LF (\n)
268				if ch == '\r' {
269					continue
270				}
271				// end of the line
272				if ch == '\n' {
273					// newlines can be escaped to chain arguments
274					// onto multiple lines; else, increment the line count
275					if escaped {
276						l.skippedLines++
277						escaped = false
278					} else {
279						l.line += 1 + l.skippedLines
280						l.skippedLines = 0
281					}
282					// comments (#) are single-line only
283					comment = false
284				}
285				// any kind of space means we're at the end of this token
286				if len(val) > 0 {
287					return makeToken(0, false), nil
288				}
289				continue
290			}
291	
292			// comments must be at the start of a token,
293			// in other words, preceded by space or newline
294			if ch == '#' && len(val) == 0 {
295				comment = true
296			}
297			if comment {
298				continue
299			}
300	
301			if len(val) == 0 {
302				l.token = Token{Line: l.line}
303				if ch == '"' {
304					quoted = true
305					continue
306				}
307				if ch == '`' {
308					btQuoted = true
309					continue
310				}
311			}
312	
313			if escaped {
314				// allow escaping the first < to skip the heredoc syntax
315				if ch == '<' {
316					heredocEscaped = true
317				} else {
318					val = append(val, '\\')
319				}
320				escaped = false
321			}
322	
323			val = append(val, ch)
324		}
325	}
326	
327	// finalizeHeredoc takes the runes read as the heredoc text and the marker,
328	// and processes the text to strip leading whitespace, returning the final
329	// value without the leading whitespace.
330	func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
331		stringVal := string(val)
332	
333		// find the last newline of the heredoc, which is where the contents end
334		lastNewline := strings.LastIndex(stringVal, "\n")
335	
336		// collapse the content, then split into separate lines
337		lines := strings.Split(stringVal[:lastNewline+1], "\n")
338	
339		// figure out how much whitespace we need to strip from the front of every line
340		// by getting the string that precedes the marker, on the last line
341		paddingToStrip := stringVal[lastNewline+1 : len(stringVal)-len(marker)]
342	
343		// iterate over each line and strip the whitespace from the front
344		var out string
345		for lineNum, lineText := range lines[:len(lines)-1] {
346			if lineText == "" || lineText == "\r" {
347				out += "\n"
348				continue
349			}
350	
351			// find an exact match for the padding
352			index := strings.Index(lineText, paddingToStrip)
353	
354			// if the padding doesn't match exactly at the start then we can't safely strip
355			if index != 0 {
356				cleanLineText := strings.TrimRight(lineText, "\r\n")
357				return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, l.line+lineNum+1, cleanLineText, paddingToStrip)
358			}
359	
360			// strip, then append the line, with the newline, to the output.
361			// also removes all "\r" because Windows.
362			out += strings.ReplaceAll(lineText[len(paddingToStrip):]+"\n", "\r", "")
363		}
364	
365		// Remove the trailing newline from the loop
366		if len(out) > 0 && out[len(out)-1] == '\n' {
367			out = out[:len(out)-1]
368		}
369	
370		// return the final value
371		return []rune(out), nil
372	}
373	
374	// Quoted returns true if the token was enclosed in quotes
375	// (i.e. double quotes, backticks, or heredoc).
376	func (t Token) Quoted() bool {
377		return t.wasQuoted > 0
378	}
379	
380	// NumLineBreaks counts how many line breaks are in the token text.
381	func (t Token) NumLineBreaks() int {
382		lineBreaks := strings.Count(t.Text, "\n")
383		if t.wasQuoted == '<' {
384			// heredocs have an extra linebreak because the opening
385			// delimiter is on its own line and is not included in the
386			// token Text itself, and the trailing newline is removed.
387			lineBreaks += 2
388		}
389		return lineBreaks
390	}
391	
392	// Clone returns a deep copy of the token.
393	func (t Token) Clone() Token {
394		return Token{
395			File:          t.File,
396			imports:       append([]string{}, t.imports...),
397			Line:          t.Line,
398			Text:          t.Text,
399			wasQuoted:     t.wasQuoted,
400			quoteClosed:   t.quoteClosed,
401			heredocMarker: t.heredocMarker,
402			snippetName:   t.snippetName,
403		}
404	}
405	
406	var heredocMarkerRegexp = regexp.MustCompile("^[A-Za-z0-9_-]+$")
407	
408	// isNextOnNewLine tests whether t2 is on a different line from t1
409	func isNextOnNewLine(t1, t2 Token) bool {
410		// If the second token is from a different file,
411		// we can assume it's from a different line
412		if t1.File != t2.File {
413			return true
414		}
415	
416		// If the second token is from a different import chain,
417		// we can assume it's from a different line
418		if len(t1.imports) != len(t2.imports) {
419			return true
420		}
421		for i, im := range t1.imports {
422			if im != t2.imports[i] {
423				return true
424			}
425		}
426	
427		// If the first token (incl line breaks) ends
428		// on a line earlier than the next token,
429		// then the second token is on a new line
430		return t1.Line+t1.NumLineBreaks() < t2.Line
431	}
