30	// readersFor builds a FileReaderFunc over an in-memory file set.
31	func readersFor(files map[string]string) FileReaderFunc {
32		return func(name string) (io.ReadCloser, error) {
33			contents, ok := files[normalizeImportPath(name)]
34			if !ok {
35				return nil, &fsPathError{op: "open", name: name, err: errNotExist}
36			}
37			return io.NopCloser(strings.NewReader(contents)), nil
38		}
39	}
