51	// flattenBlocks renders parsed blocks as a sequence of token-text
52	// lines: directive order and exact argument bytes are the observation
53	// surface these tests rely on.
54	func flattenBlocks(blocks []ServerBlock) [][]string {
55		var out [][]string
56		for _, b := range blocks {
57			for _, seg := range b.Segments {
58				var line []string
59				for _, tok := range seg {
60					line = append(line, tok.Text)
61				}
62				out = append(out, line)
63			}
64		}
65		return out
66	}
