520	func TestParseReadersSameInputStableBytesAndError(t *testing.T) {
521		// deterministic ordering across many globs and repeated calls
522		names := []string{"conf/m.caddy", "conf/a.caddy", "conf/z.caddy", "conf/b.caddy"}
523		all := append([]string{}, names...)
524		sort.Strings(all)
525	
526		mapfs := fstest.MapFS{
527			"Caddyfile": &fstest.MapFile{Data: []byte(":8080 {\n\timport conf/*.caddy\n}\n")},
528		}
529		for _, n := range names {
530			mapfs[n] = &fstest.MapFile{Data: []byte("d " + pathBase(n) + "\n")}
531		}
532		var first [][]string
533		for i := 0; i < 5; i++ {
534			blocks, err := Parse("Caddyfile", mapfs["Caddyfile"].Data, FromFS(mapfs))
535			if err != nil {
536				t.Fatalf("iteration %d: %v", i, err)
537			}
538			lines := flattenBlocks(blocks)
539			if first == nil {
540				first = lines
541				continue
542			}
543			if fmt.Sprintf("%v", lines) != fmt.Sprintf("%v", first) {
544				t.Fatalf("iteration %d: %v != %v", i, lines, first)
545			}
546		}
547		want := make([][]string, 0, len(all))
548		for _, n := range all {
549			want = append(want, []string{"d", pathBase(n)})
550		}
551		assertLines(t, want, first)
552	
553		// identical failing inputs produce identical error text regardless
554		// of call index
555		failing := map[string]string{
556			"Caddyfile": ":8080 {\n\timport f.caddy\n}\n",
557			"f.caddy":   "d {args[9]}\n",
558		}
559		var msg string
560		for i := 0; i < 3; i++ {
561			_, err := Parse("Caddyfile", []byte(failing["Caddyfile"]), readersFor(failing))
562			if err == nil {
563				t.Fatal("expected failure")
564			}
565			if msg == "" {
566				msg = err.Error()
567			} else if err.Error() != msg {
568				t.Fatalf("unstable error text:\n%s\n%s", msg, err.Error())
569			}
570		}
571	}
572	
573	func pathBase(p string) string {
574		if i := strings.LastIndex(p, "/"); i >= 0 {
575			return p[i+1:]
576		}
577		return p
578	}
