package caddyfile

import (
	"io"
	"strings"
	"testing"
)

func TestScratchBracesInArgNotReexpanded(t *testing.T) {
	files := map[string]string{
		"Caddyfile": ":8080 {\n\timport f.caddy '{args[1]}'\n}\n",
		"f.caddy":   "x {args[0]}\n",
	}
	blocks, err := Parse("Caddyfile", []byte(files["Caddyfile"]), readersFor(files))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	lines := flattenBlocks(blocks)
	assertLines(t, [][]string{{"x", "{args[1]}"}}, lines)
}

func TestScratchFirstFailureStable(t *testing.T) {
	mkFiles := func() map[string]string {
		return map[string]string{
			"Caddyfile": "import a.caddy\n",
			"a.caddy":   "import b.caddy\nimport c.caddy\n",
			"b.caddy":   "ok-b\n",
			"c.caddy":   "bad {args[9]}\n",
			"d.caddy":   "also-bad {args[-1]}\n",
		}
	}
	var first string
	for i := 0; i < 3; i++ {
		files := mkFiles()
		blocks, err := Parse("Caddyfile", []byte(files["Caddyfile"]), readersFor(files))
		if err == nil {
			t.Fatal("expected failure")
		}
		if blocks != nil {
			t.Fatal("failed parse returned blocks")
		}
		if !strings.Contains(err.Error(), "c.caddy:1") {
			t.Fatalf("want first failure at c.caddy:1, got %v", err)
		}
		if first == "" {
			first = err.Error()
		} else if err.Error() != first {
			t.Fatalf("unstable error:\n%s\n%s", first, err.Error())
		}
	}

	// immediately retry same top-level name with a different tree
	files2 := map[string]string{
		"Caddyfile": ":8080 {\n\timport a.caddy\n}\n",
		"a.caddy":   "fresh value\n",
	}
	readers2 := FileReaderFunc(func(name string) (io.ReadCloser, error) {
		return io.NopCloser(strings.NewReader(files2[name])), nil
	})
	blocks, err := Parse("Caddyfile", []byte(files2["Caddyfile"]), readers2)
	if err != nil {
		t.Fatalf("retry failed: %v", err)
	}
	assertLines(t, [][]string{{"fresh", "value"}}, flattenBlocks(blocks))
}

